package com.cbdog.ptvbox
import org.junit.Test
import org.junit.Assert.*
class Version051Test {
 @Test fun onlyLastDataRowCanRequestNextPage(){val keys=setOf<Any>("a","b","c","d");val visible=listOf(Triple<Any,Int,Int>("header",0,0),Triple("a",1,1),Triple("b",1,2),Triple("c",2,3),Triple("d",2,4));assertFalse(lastRow051("a",keys,visible));assertTrue(lastRow051("c",keys,visible));assertTrue(lastRow051("d",keys,visible));assertFalse(lastRow051("c",keys,visible.dropLast(1)))}
 @Test fun hiddenBackExitsAndVisibleBackOnlyHides(){val hidden=PlayerOverlay(controls=false);assertTrue(hidden.back().second);val visible=PlayerOverlay();assertFalse(visible.back().second);assertFalse(visible.back().first.controls)}
 @Test fun movieVariantsAreNotEpisodes(){val s=Site("s","站","https://example.org");val a=Candidate(s,"1080p",Episode("2GB","https://example.org/a"));val b=Candidate(s,"2160p",Episode("39GB","https://example.org/b"));assertEquals(listOf("2GB"),Episodes051.names("movie","2GB",a,listOf(a,b),emptyMap()))}
 @Test fun sameRouteMoviePartsAreEpisodes(){val s=Site("s","站","https://example.org");val a=Candidate(s,"双碟",Episode("上部","https://example.org/a"));val eps=listOf(Episode("上部","a"),Episode("下部","b"));assertEquals(listOf("上部","下部"),Episodes051.names("movie","上部",a,listOf(a),mapOf("s|双碟" to eps)))}
 @Test fun failedSeekKeepsRequestedPositionWhenPlayerResetToZero(){assertEquals(180000L,Episodes051.fallbackPosition(0,180000));assertEquals(181500L,Episodes051.fallbackPosition(181500,180000));assertEquals(0L,Episodes051.fallbackPosition(-1,0))}
 @Test fun stremioNullTitleRetainsDescriptionAndSortsSize(){val raw=org.json.JSONObject("""{"streams":[{"name":"4K","title":null,"description":"2160p HDR 39 GB","url":"https://example.org/a","behaviorHints":{"videoSize":41875931136}},{"name":"HD","title":null,"description":"1080p","url":"https://example.org/b","behaviorHints":{"videoSize":2147483648}}]}""");val v=Stremio050.parse(Site("s","HDHUB","https://example.org",8),Work("1","甲"),"正片",raw);assertTrue(v.roads.first().name.contains("1080p"));assertTrue(v.roads.last().name.contains("HDR"));assertFalse(v.roads.first().name.contains("null"));assertEquals(2L*1024*1024*1024,ResourceLabels040.bytes(v.roads.first().name))}
 @Test fun promotionalStreamsAreNotMovieLines(){val raw=org.json.JSONObject("""{"streams":[{"name":"Donation needed.","url":"https://example.org/promo.mp4"},{"name":"HDHUB 1080p","url":"https://example.org/movie.mp4"}]}""");assertEquals(1,Stremio050.parse(Site("s","站","https://example.org",8),Work("1","甲"),"正片",raw).roads.size)}
 private fun hex(s:String)=s.chunked(2).map{it.toInt(16).toByte()}.toByteArray()
 @Test fun chainedMatroskaSeekHeadResolvesRealCuesWithoutChangingOffsets(){val head=hex("1a45dfa3a34286810142f7810142f2810442f381084282886d6174726f736b6142878104428581021853806701000000347ddfba114d9b74914dbb8e53ab84114d9b7453ac84347ddf67");val tail=hex("114d9b74914dbb8e53ab841c53bb6b53ac84347b292b");var requests=0;val patch=MkvSeek051.patch(head){at->assertEquals(52L+0x347ddf67L,at);requests++;tail}!!;val updated=head.copyOf();patch.bytes.forEach{(at,b)->updated[at.toInt()]=b};assertEquals(1,requests);assertEquals(head.size,updated.size);assertArrayEquals(hex("1c53bb6b"),updated.copyOfRange(63,67));assertArrayEquals(hex("347b292b"),updated.copyOfRange(70,74));assertNull(MkvSeek051.patch(updated){error("direct cues must use native extractor")})}
 @Test fun invalidChainedIndexCannotInventSeekPositions(){val bad=hex("1a45dfa3");assertNull(MkvSeek051.patch(bad){error("no request")})}
}
